// Abstract Shape Circle and Triangle
public class Q07 {abstract static class Shape {abstract double calculateArea();abstract double calculatePerimeter();} static class Circle extends Shape {double r; Circle(double r){this.r=r;} double calculateArea(){return Math.PI*r*r;} double calculatePerimeter(){return 2*Math.PI*r;}} static class Triangle extends Shape {double a,b,c;Triangle(double a,double b,double c){this.a=a;this.b=b;this.c=c;}double calculatePerimeter(){return a+b+c;}double calculateArea(){double s=calculatePerimeter()/2;return Math.sqrt(s*(s-a)*(s-b)*(s-c));}}public static void main(String[] args){Shape[] ss={new Circle(3),new Triangle(3,4,5)};for(Shape s:ss)System.out.printf("Area: %.2f, Perimeter: %.2f%n",s.calculateArea(),s.calculatePerimeter());}}
